import AppKit
import CoreText
import Foundation

struct Box {
    var minX = Double.greatestFiniteMagnitude
    var minY = Double.greatestFiniteMagnitude
    var maxX = -Double.greatestFiniteMagnitude
    var maxY = -Double.greatestFiniteMagnitude

    mutating func include(_ p: CGPoint) {
        minX = min(minX, Double(p.x))
        minY = min(minY, Double(p.y))
        maxX = max(maxX, Double(p.x))
        maxY = max(maxY, Double(p.y))
    }
}

func font(named name: String, size: CGFloat) -> NSFont {
    guard let font = NSFont(name: name, size: size) else {
        fputs("missing font \(name)\n", stderr)
        exit(1)
    }
    return font
}

func outline(_ text: String, font: NSFont, origin: CGPoint) -> (String, Box) {
    let attr = NSAttributedString(string: text, attributes: [.font: font])
    let line = CTLineCreateWithAttributedString(attr)
    var d = CGAffineTransform(translationX: origin.x, y: origin.y)
    guard let path = CTLineCreatePath(line, &d) else {
        return ("", Box())
    }
    var svg = ""
    var box = Box()
    path.applyWithBlock { ptr in
        let el = ptr.pointee
        switch el.type {
        case .moveToPoint:
            let p = el.points[0]
            box.include(p)
            svg += String(format: "M%.2f %.2f ", p.x, p.y)
        case .addLineToPoint:
            let p = el.points[0]
            box.include(p)
            svg += String(format: "L%.2f %.2f ", p.x, p.y)
        case .addQuadCurveToPoint:
            let c = el.points[0]
            let p = el.points[1]
            box.include(c)
            box.include(p)
            svg += String(format: "Q%.2f %.2f %.2f %.2f ", c.x, c.y, p.x, p.y)
        case .addCurveToPoint:
            let c1 = el.points[0]
            let c2 = el.points[1]
            let p = el.points[2]
            box.include(c1)
            box.include(c2)
            box.include(p)
            svg += String(format: "C%.2f %.2f %.2f %.2f %.2f %.2f ", c1.x, c1.y, c2.x, c2.y, p.x, p.y)
        case .closeSubpath:
            svg += "Z "
        @unknown default:
            break
        }
    }
    return (svg, box)
}

func writeSVG(path: String, d: String, box: Box, fill: String, pad: Double) {
    let w = box.maxX - box.minX + pad * 2
    let h = box.maxY - box.minY + pad * 2
    let tx = -box.minX + pad
    let ty = box.maxY + pad
    let svg = """
    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 \(String(format: "%.2f", w)) \(String(format: "%.2f", h))" role="img" aria-label="shy">
      <path fill="\(fill)" transform="matrix(1 0 0 -1 \(String(format: "%.2f", tx)) \(String(format: "%.2f", ty)))" d="\(d.trimmingCharacters(in: .whitespaces))"/>
    </svg>

    """
    try! svg.write(toFile: path, atomically: true, encoding: .utf8)
}

let mono = font(named: "Menlo-Regular", size: 220)
let serif = font(named: "Georgia-Italic", size: 248)

let (sh, shBox) = outline("SH", font: mono, origin: .zero)
let yOrigin = CGPoint(x: shBox.maxX - 6, y: -2)
let (y, yBox) = outline("y", font: serif, origin: yOrigin)

var box = shBox
box.include(CGPoint(x: yBox.minX, y: yBox.minY))
box.include(CGPoint(x: yBox.maxX, y: yBox.maxY))

let outDir = CommandLine.arguments.count > 1 ? CommandLine.arguments[1] : "."
writeSVG(path: "\(outDir)/logo.svg", d: sh + y, box: box, fill: "#1d1a16", pad: 36)
writeSVG(path: "\(outDir)/logo-green.svg", d: sh + y, box: box, fill: "#0f6e56", pad: 36)

// Tight square mark: same paths, more padding so the descender has air.
writeSVG(path: "\(outDir)/mark.svg", d: sh + y, box: box, fill: "#1d1a16", pad: 72)
print("ok \(outDir)")

import AppKit
import CoreText
import Foundation

struct Box {
    var minX = Double.greatestFiniteMagnitude
    var minY = Double.greatestFiniteMagnitude
    var maxX = -Double.greatestFiniteMagnitude
    var maxY = -Double.greatestFiniteMagnitude

    mutating func include(_ p: CGPoint) {
        minX = min(minX, Double(p.x))
        minY = min(minY, Double(p.y))
        maxX = max(maxX, Double(p.x))
        maxY = max(maxY, Double(p.y))
    }
}

func ctFont(named name: String, size: CGFloat) -> CTFont {
    let font = CTFontCreateWithName(name as CFString, size, nil)
    let actual = CTFontCopyPostScriptName(font) as String
    if actual.caseInsensitiveCompare(name) != .orderedSame,
       !actual.lowercased().contains(name.split(separator: "-").first!.lowercased()) {
        fputs("wanted \(name), got \(actual)\n", stderr)
    }
    return font
}

func outline(_ text: String, font: CTFont, origin: CGPoint) -> (String, Box, CGFloat) {
    var chars = Array(text.utf16)
    var glyphs = [CGGlyph](repeating: 0, count: chars.count)
    var advances = [CGSize](repeating: .zero, count: chars.count)
    CTFontGetGlyphsForCharacters(font, &chars, &glyphs, chars.count)
    CTFontGetAdvancesForGlyphs(font, .default, glyphs, &advances, chars.count)

    var svg = ""
    var box = Box()
    var x = origin.x
    let y = origin.y
    for (i, glyph) in glyphs.enumerated() {
        var t = CGAffineTransform(translationX: x, y: y)
        guard let path = CTFontCreatePathForGlyph(font, glyph, &t) else {
            x += advances[i].width
            continue
        }
        path.applyWithBlock { ptr in
            let el = ptr.pointee
            switch el.type {
            case .moveToPoint:
                let p = el.points[0]
                box.include(p)
                svg += String(format: "M%.2f %.2f ", p.x, p.y)
            case .addLineToPoint:
                let p = el.points[0]
                box.include(p)
                svg += String(format: "L%.2f %.2f ", p.x, p.y)
            case .addQuadCurveToPoint:
                let c = el.points[0]
                let p = el.points[1]
                box.include(c)
                box.include(p)
                svg += String(format: "Q%.2f %.2f %.2f %.2f ", c.x, c.y, p.x, p.y)
            case .addCurveToPoint:
                let c1 = el.points[0]
                let c2 = el.points[1]
                let p = el.points[2]
                box.include(c1)
                box.include(c2)
                box.include(p)
                svg += String(format: "C%.2f %.2f %.2f %.2f %.2f %.2f ", c1.x, c1.y, c2.x, c2.y, p.x, p.y)
            case .closeSubpath:
                svg += "Z "
            @unknown default:
                break
            }
        }
        x += advances[i].width
    }
    return (svg, box, x - origin.x)
}

func writeSVG(path: String, d: String, box: Box, fill: String, pad: Double) {
    let w = box.maxX - box.minX + pad * 2
    let h = box.maxY - box.minY + pad * 2
    let tx = -box.minX + pad
    let ty = box.maxY + pad
    let svg = """
    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 \(String(format: "%.2f", w)) \(String(format: "%.2f", h))" role="img" aria-label="shy">
      <path fill="\(fill)" transform="matrix(1 0 0 -1 \(String(format: "%.2f", tx)) \(String(format: "%.2f", ty)))" d="\(d.trimmingCharacters(in: .whitespaces))"/>
    </svg>

    """
    try! svg.write(toFile: path, atomically: true, encoding: .utf8)
}

let mono = ctFont(named: "Menlo-Regular", size: 220)
let serif = ctFont(named: "Georgia-Italic", size: 248)

let (sh, shBox, shWidth) = outline("SH", font: mono, origin: .zero)
let yOrigin = CGPoint(x: shWidth - 8, y: 0)
let (y, yBox, _) = outline("y", font: serif, origin: yOrigin)

var box = shBox
box.include(CGPoint(x: yBox.minX, y: yBox.minY))
box.include(CGPoint(x: yBox.maxX, y: yBox.maxY))

let outDir = CommandLine.arguments.count > 1 ? CommandLine.arguments[1] : "."
writeSVG(path: "\(outDir)/logo.svg", d: sh + y, box: box, fill: "#1d1a16", pad: 36)
writeSVG(path: "\(outDir)/logo-green.svg", d: sh + y, box: box, fill: "#0f6e56", pad: 36)
writeSVG(path: "\(outDir)/mark.svg", d: sh + y, box: box, fill: "#1d1a16", pad: 72)
print("ok \(outDir) box=\(box.minX),\(box.minY) \(box.maxX),\(box.maxY)")

import AppKit
import Foundation

let src = CommandLine.arguments[1]
let dst = CommandLine.arguments[2]
let width = (CommandLine.arguments.count > 3 ? Int(CommandLine.arguments[3]) : 900) ?? 900

guard let svg = NSImage(contentsOfFile: src) else {
    fputs("could not load \(src)\n", stderr)
    exit(1)
}
let size = svg.size
let scale = CGFloat(width) / max(size.width, 1)
let px = NSSize(width: size.width * scale, height: size.height * scale)
let img = NSImage(size: px)
img.lockFocus()
NSColor(calibratedRed: 1, green: 0.992, blue: 0.973, alpha: 1).setFill()
NSBezierPath(rect: NSRect(origin: .zero, size: px)).fill()
svg.draw(in: NSRect(origin: .zero, size: px), from: .zero, operation: .sourceOver, fraction: 1)
img.unlockFocus()

guard let tiff = img.tiffRepresentation,
      let rep = NSBitmapImageRep(data: tiff),
      let png = rep.representation(using: .png, properties: [:]) else {
    fputs("encode failed\n", stderr)
    exit(1)
}
try png.write(to: URL(fileURLWithPath: dst))
print("wrote \(dst) \(Int(px.width))x\(Int(px.height))")

