import AppKit
import CoreText
import Foundation

let ink = NSColor(calibratedRed: 0x1d/255, green: 0x1a/255, blue: 0x16/255, alpha: 1)
let cream = NSColor(calibratedRed: 1, green: 0.992, blue: 0.973, alpha: 1)
