struct Placed {
    let d: String
    let box: (CGFloat, CGFloat, CGFloat, CGFloat) // minx miny maxx maxy in path space
}

func outline(_ text: String, name: String, size: CGFloat, origin: CGPoint) -> (String, CGRect) {
