        var t = CGAffineTransform(translationX: x, y: origin.y)
        if let path = CTFontCreatePathForGlyph(font, glyph, &t) {
            box = box.union(path.boundingBoxOfPath)
            path.applyWithBlock { ptr in
                let el = ptr.pointee
                switch el.type {
                case .moveToPoint:
                    let p = el.points[0]
                    svg += String(format: "M%.2f %.2f ", p.x, p.y)
                case .addLineToPoint:
                    let p = el.points[0]
                    svg += String(format: "L%.2f %.2f ", p.x, p.y)
                case .addQuadCurveToPoint:
