}

func boundsOf(_ text: String, name: String, size: CGFloat) -> (CGRect, CGFloat) {
    let (_, box) = outline(text, name: name, size: size, origin: .zero)
    let font = CTFontCreateWithName(name as CFString, size, nil)
    var chars = Array(text.utf16)
    var glyphs = [CGGlyph](repeating: 0, count: chars.count)
    var advances = [CGSize](repeating: .zero, count: chars.count)
    CTFontGetGlyphsForCharacters(font, &chars, &glyphs, chars.count)
    CTFontGetAdvancesForGlyphs(font, .default, glyphs, &advances, chars.count)
    let adv = advances.reduce(0) { $0 + $1.width }
    return (box, adv)
}

// xHeightRatio: serif x-height / mono cap-height
func lockup(mono: String, serif: String, monoSize: CGFloat, xRatio: CGFloat, gap: CGFloat, shKern: CGFloat) -> (String, CGRect) {
    let monoFont = CTFontCreateWithName(mono as CFString, monoSize, nil)
    let cap = CTFontGetCapHeight(monoFont)
    // find serif size whose x-height == xRatio * cap
    var lo: CGFloat = 10
    var hi: CGFloat = monoSize * 3
    for _ in 0..<24 {
        let mid = (lo + hi) / 2
        let f = CTFontCreateWithName(serif as CFString, mid, nil)
        if CTFontGetXHeight(f) < cap * xRatio { lo = mid } else { hi = mid }
    }
    let serifSize = (lo + hi) / 2
    let (sBox, _) = boundsOf("S", name: mono, size: monoSize)
    let (hBox, _) = boundsOf("H", name: mono, size: monoSize)
    let (yBox, _) = boundsOf("y", name: serif, size: serifSize)

    // place S at x=0 baseline 0. Then H so the gap between ink is `gap`, pulled by shKern.
    let sRight = sBox.maxX
    let hShift = sRight + gap - hBox.minX - shKern
    let hRight = hBox.maxX + hShift
    let yShift = hRight + gap * 0.45 - yBox.minX

    let (s, _) = outline("S", name: mono, size: monoSize, origin: .zero)
    let (h, _) = outline("H", name: mono, size: monoSize, origin: CGPoint(x: hShift, y: 0))
    let (y, yb) = outline("y", name: serif, size: serifSize, origin: CGPoint(x: yShift, y: 0))
    var box = sBox
    box = box.union(hBox.offsetBy(dx: hShift, dy: 0))
    box = box.union(yb)
    return (s + h + y, box)
}

struct Row {
    let mono: String
    let serif: String
    let ratio: CGFloat
    let gap: CGFloat
    let kern: CGFloat
    let label: String
}

let rows: [Row] = [
