    Row(mono: "Menlo-Regular", serif: "Didot-Italic", ratio: 0.68, gap: 12, kern: 4, label: "menlo / didot italic"),
    Row(mono: "PTMono-Regular", serif: "Baskerville-Italic", ratio: 0.66, gap: 8, kern: 6, label: "pt mono / baskerville italic"),
]

