for (i, row) in rows.enumerated() {
    let (d, box) = lockup(mono: row.mono, serif: row.serif, monoSize: 150, xRatio: row.ratio, gap: row.gap, kern: row.kern)
    let pad: CGFloat = 24
    let bw = box.width + pad * 2
    let bh = box.height + pad * 2
    // flip into top-down row
    let rowY = H - 40 - CGFloat(i) * 230
    let scale: CGFloat = min(1, 900 / bw)
    let tx = 40 - box.minX * scale
    let ty = rowY - box.maxY * scale
    let svg = """
    <svg xmlns="http://www.w3.org/2000/svg" width="\(bw)" height="\(bh)">
      <g transform="translate(\(-box.minX + pad) \(box.maxY + pad)) scale(1 -1)">
        <path fill="#1d1a16" d="\(d)"/>
      </g>
    </svg>
    """
    let url = URL(fileURLWithPath: "/tmp/row\(i).svg")
    try! svg.write(to: url, atomically: true, encoding: .utf8)
    if let piece = NSImage(contentsOf: url) {
        let dw = box.width * scale + pad * 2 * scale
        let dh = box.height * scale + pad * 2 * scale
        piece.draw(in: NSRect(x: 30, y: rowY - dh, width: dw, height: dh))
    }
    let attrs: [NSAttributedString.Key: Any] = [
        .font: NSFont.systemFont(ofSize: 13),
        .foregroundColor: NSColor.darkGray
    ]
    NSAttributedString(string: row.label, attributes: attrs).draw(at: NSPoint(x: 40, y: rowY + 8))
}
img.unlockFocus()
let png = NSBitmapImageRep(data: img.tiffRepresentation!)!.representation(using: .png, properties: [:])!
try png.write(to: URL(fileURLWithPath: "/tmp/lockups.png"))
print("wrote lockups")
