    }
    return (svg, box)
}

func bounds(_ text: String, name: String, size: CGFloat) -> CGRect {
    outline(text, name: name, size: size, origin: .zero).1
}

func serifSize(mono: String, serif: String, monoSize: CGFloat, xRatio: CGFloat) -> CGFloat {
    let cap = CTFontGetCapHeight(CTFontCreateWithName(mono as CFString, monoSize, nil))
    var lo: CGFloat = 10, hi: CGFloat = monoSize * 4
    for _ in 0..<28 {
        let mid = (lo+hi)/2
        let xh = CTFontGetXHeight(CTFontCreateWithName(serif as CFString, mid, nil))
        if xh < cap * xRatio { lo = mid } else { hi = mid }
    }
    return (lo+hi)/2
}

func emit(file: String, mono: String, serif: String, ratio: CGFloat, gap: CGFloat, pull: CGFloat) {
    let ms: CGFloat = 200
    let ss = serifSize(mono: mono, serif: serif, monoSize: ms, xRatio: ratio)
    let sBox = bounds("S", name: mono, size: ms)
    let hBox = bounds("H", name: mono, size: ms)
    let yBox = bounds("y", name: serif, size: ss)
    let hShift = sBox.maxX + gap - hBox.minX - pull
    let yShift = hBox.maxX + hShift + gap * 0.35 - yBox.minX
    let (s, _) = outline("S", name: mono, size: ms, origin: .zero)
    let (h, hb) = outline("H", name: mono, size: ms, origin: CGPoint(x: hShift, y: 0))
    let (y, yb) = outline("y", name: serif, size: ss, origin: CGPoint(x: yShift, y: 0))
    var box = sBox.union(hb).union(yb)
    let pad: CGFloat = 28
    let w = box.width + pad*2
    let h = box.height + pad*2
    let tx = -box.minX + pad
