import AppKit
import Foundation
import CoreGraphics

struct V { var x: CGFloat; var y: CGFloat }

func spineS() -> [V] {
    var pts: [V] = []
    let n = 90
    let cx: CGFloat = 38
    let rx: CGFloat = 24
    let top: CGFloat = 96
    let bot: CGFloat = 6
    for i in 0...n {
        let t = CGFloat(i) / CGFloat(n)
        // dwell on the bowls: ease the vertical a little less than linear near ends
        let u = t
        let y = top - u * (top - bot)
        let x = cx + rx * cos(u * .pi * 3)
        pts.append(V(x: x, y: y))
    }
    return pts
}

func spineY() -> [V] {
    // right stem of the y, including a short hook. y-up.
    var pts: [V] = []
    let n = 28
    for i in 0...n {
        let t = CGFloat(i) / CGFloat(n)
        let x: CGFloat = 196 + t * 16
        let y: CGFloat = 62 - t * 60
        pts.append(V(x: x, y: y))
    }
    // hook: quadratic-ish via samples, curling left and slightly down, then up into a blunt end
    let n2 = 22
    for i in 1...n2 {
        let t = CGFloat(i) / CGFloat(n2)
        // angle from straight down-ish to the left
        let a = (-0.15 - t * 2.15)
        let r: CGFloat = 16
        let pivot = pts.last!
        // accumulate small steps instead of a circle around a fixed pivot
        _ = pivot; _ = a; _ = r
    }
    // explicit hook samples from the stem end
    let hook: [V] = [
        V(x: 214, y: -2),
        V(x: 218, y: -10),
        V(x: 214, y: -18),
        V(x: 204, y: -22),
        V(x: 194, y: -20),
        V(x: 190, y: -14),
    ]
    pts.append(contentsOf: hook)
    return pts
}

func spineArm() -> [V] {
    [V(x: 166, y: 60), V(x: 188, y: 28)]
}

func offset(_ pts: [V], width: CGFloat) -> CGPath {
    func norm(_ i: Int) -> V {
        let a = i == 0 ? pts[0] : pts[i - 1]
        let b = i == pts.count - 1 ? pts[i] : pts[i + 1]
        let dx = (i == 0 ? pts[1].x - pts[0].x : b.x - a.x)
        let dy = (i == 0 ? pts[1].y - pts[0].y : b.y - a.y)
        let L = max(1e-4, hypot(dx, dy))
        return V(x: -dy / L * width, y: dx / L * width)
    }
    var left: [V] = []
    var right: [V] = []
    for i in 0..<pts.count {
        let n = norm(i)
        left.append(V(x: pts[i].x + n.x, y: pts[i].y + n.y))
        right.append(V(x: pts[i].x - n.x, y: pts[i].y - n.y))
    }
    let p = CGMutablePath()
