import AppKit
import CoreText
import Foundation

func font(_ n: String, _ s: CGFloat) -> CTFont { CTFontCreateWithName(n as CFString, s, nil) }
func glyphs(_ text: String, _ f: CTFont, _ o: CGPoint) -> (CGPath, CGFloat) {
    var chars = Array(text.utf16)
    var gs = [CGGlyph](repeating: 0, count: chars.count)
    var adv = [CGSize](repeating: .zero, count: chars.count)
    CTFontGetGlyphsForCharacters(f, &chars, &gs, chars.count)
    CTFontGetAdvancesForGlyphs(f, .default, gs, &adv, chars.count)
    let out = CGMutablePath()
    var x = o.x
    for (i, g) in gs.enumerated() {
        var t = CGAffineTransform(translationX: x, y: o.y)
        if let p = CTFontCreatePathForGlyph(f, g, &t) { out.addPath(p) }
        x += adv[i].width
    }
    return (out, x - o.x)
}
func ink(_ t: String, _ n: String, _ s: CGFloat) -> CGRect { glyphs(t, font(n, s), .zero).0.boundingBoxOfPath }

func make(ratio: CGFloat, gap: CGFloat) -> CGPath {
    let mono = "PTMono-Bold", serif = "Georgia-Italic"
    let ms: CGFloat = 240
    let cap = CTFontGetCapHeight(font(mono, ms))
    var lo: CGFloat = 8, hi = ms * 3
    for _ in 0..<30 {
        let mid = (lo+hi)/2
        if CTFontGetXHeight(font(serif, mid)) < cap * ratio { lo = mid } else { hi = mid }
    }
    let ss = (lo+hi)/2
    let sBox = ink("S", mono, ms)
    let hBox = ink("H", mono, ms)
    let yBox = ink("y", serif, ss)
    let pull: CGFloat = 22
    let hShift = sBox.maxX + gap - hBox.minX - pull
    let yShift = hBox.maxX + hShift + gap - yBox.minX
    let out = CGMutablePath()
    out.addPath(glyphs("S", font(mono, ms), .zero).0)
    out.addPath(glyphs("H", font(mono, ms), CGPoint(x: hShift, y: 0)).0)
    out.addPath(glyphs("y", font(serif, ss), CGPoint(x: yShift, y: 0)).0)
    return out
}

