func yGlyph(hook: CGFloat) -> CGPath {
    // local coords, baseline y=0, x-height ~64. Thick stem, thin arm, short hook, a serif flag.
    let stem = CGMutablePath()
    stem.move(to: CGPoint(x: 18, y: 66))
    stem.addLine(to: CGPoint(x: 30, y: 2))
    stem.addQuadCurve(to: CGPoint(x: 8, y: -hook), control: CGPoint(x: 40, y: -hook * 0.15))
    stem.addQuadCurve(to: CGPoint(x: 2, y: -hook + 6), control: CGPoint(x: 0, y: -hook - 4))
    let thick = stem.copy(strokingWithWidth: 13, lineCap: .round, lineJoin: .round, miterLimit: 2)
    let arm = CGMutablePath()
    arm.move(to: CGPoint(x: -6, y: 62))
    arm.addQuadCurve(to: CGPoint(x: 20, y: 24), control: CGPoint(x: 4, y: 40))
    let thin = arm.copy(strokingWithWidth: 6.5, lineCap: .round, lineJoin: .round, miterLimit: 2)
    let flag = CGMutablePath()
    flag.move(to: CGPoint(x: 6, y: 60))
    flag.addLine(to: CGPoint(x: 26, y: 72))
    flag.addLine(to: CGPoint(x: 30, y: 66))
    flag.addLine(to: CGPoint(x: 12, y: 56))
    flag.closeSubpath()
    let out = CGMutablePath()
    out.addPath(thick)
    out.addPath(thin)
    out.addPath(flag)
    return out
}

func wordmark(hook: CGFloat) -> CGPath {
    let s = ess()
    let sb = s.boundingBoxOfPath
    let stroke: CGFloat = 15
    let gap: CGFloat = 8
    let hLeft = sb.maxX + gap
    let hWidth: CGFloat = 62
