func georgiaY() -> (CGPath, CGFloat) {
    let size: CGFloat = 100
    let f = CTFontCreateWithName("Georgia-Italic" as CFString, size, nil)
    let xh = CTFontGetXHeight(f)
    var chars = Array("y".utf16)
    var gs = [CGGlyph](repeating: 0, count: 1)
    CTFontGetGlyphsForCharacters(f, &chars, &gs, 1)
    var t = CGAffineTransform.identity
    let p = CTFontCreatePathForGlyph(f, gs[0], &t)!
    return (p, xh)
}

func wordmark() -> CGPath {
    let s = ess()
    let sb = s.boundingBoxOfPath
    let stroke: CGFloat = 15
    let gap: CGFloat = 10
    let hLeft = sb.maxX + gap
    let hWidth: CGFloat = 64
    let out = CGMutablePath()
    out.addPath(s)
    out.addRect(CGRect(x: hLeft, y: sb.minY, width: stroke, height: sb.height))
    out.addRect(CGRect(x: hLeft + hWidth - stroke, y: sb.minY, width: stroke, height: sb.height))
    out.addRect(CGRect(x: hLeft + stroke, y: sb.midY - stroke/2, width: hWidth - stroke*2, height: stroke))
    let (y, xh) = georgiaY()
    let scale = (sb.height * 0.70) / xh
    let yb = y.boundingBoxOfPath.applying(CGAffineTransform(scaleX: scale, y: scale))
    // baseline of georgia y is y=0. Align baseline with S baseline (sb.minY) plus a small sit.
    // After scale, baseline still 0. S baseline is sb.minY.
    let dx = hLeft + hWidth + 4 - yb.minX
    let dy = sb.minY
    var tr = CGAffineTransform(scaleX: scale, y: scale)
    tr = tr.translatedBy(x: dx / scale, y: dy / scale)
    // Careful: scale then translate in the glyph's space.
    // We want final = scale * p + (dx, dy) but dy should put baseline at sb.minY,
    // and the glyph's leftmost at dx.
    // p' = p * scale + offset
    // minX' = y.bounds.minX * scale + offset.x = hLeft+hWidth+4
    // baseline 0 maps to offset.y = sb.minY
    let ybox = y.boundingBoxOfPath
    let ox = hLeft + hWidth + 6 - ybox.minX * scale
    let oy = sb.minY
    var placed = CGAffineTransform(scaleX: scale, y: scale).translatedBy(x: ox / scale, y: oy / scale)
    // CGAffineTransform concat order: translatedBy after scaleX means T * S, applied to points as T*(S*p) if it's the new = old.concatenated(T)? 
    // In Swift, `A.translatedBy` returns a transform that is A then translation in the transformed system... 
    // Safer: build path by applying explicitly.
    let scaled = CGMutablePath()
    scaled.addPath(y, transform: CGAffineTransform(scaleX: scale, y: scale))
    let sb2 = scaled.boundingBoxOfPath
    let ox2 = hLeft + hWidth + 6 - sb2.minX
    // baseline: point (0,0) scaled stays 0. We want it at sb.minY.
    let oy2 = sb.minY
    out.addPath(scaled, transform: CGAffineTransform(translationX: ox2, y: oy2))
    _ = tr; _ = placed; _ = yb
    return out
}

